**C program to reverse a string**

```c
#include <stdio.h>
#include <string.h>
void reverse(char s[]) {
    int i, len = strlen(s);
    char temp;
    for (i = 0; i < len / 2; i++) {
        temp = s[i];
        s[i] = s[len - 1 - i];
        s[len - 1 - i] = temp;
    }
